// Calculate area of a simple polygon given its vertices in order
function polygonArea(points) {
    // Validate input
    if (!Array.isArray(points)) {
        throw new Error("polygonArea: points must be an array");
    }
    if (points.length < 3) {
        throw new Error("polygonArea: a polygon must have at least 3 vertices");
    }

    for (let i = 0; i < points.length; i++) {
        const point = points[i];
        if (!point || typeof point !== 'object' || point.x === undefined || point.y === undefined) {
            throw new Error(`polygonArea: point at index ${i} must be an object with x and y properties`);
        }
        if (typeof point.x !== 'number' || !isFinite(point.x)) {
            throw new Error(`polygonArea: point at index ${i} has invalid x coordinate: ${point.x}`);
        }
        if (typeof point.y !== 'number' || !isFinite(point.y)) {
            throw new Error(`polygonArea: point at index ${i} has invalid y coordinate: ${point.y}`);
        }
    }

    let area = 0;
    const n = points.length;

    for (let i = 0; i < n; i++) {
        const j = (i + 1) % n;
        area += points[i].x * points[j].y;
        area -= points[j].x * points[i].y;
    }

    return Math.abs(area) / 2;
}

